<script>(()=>{const period=document.getElementById('invoice-period'),month=document.getElementById('invoice-month'),from=document.getElementById('invoice-from'),to=document.getElementById('invoice-to'),monthField=document.getElementById('invoice-month-field'),fromField=document.getElementById('invoice-from-field'),toField=document.getElementById('invoice-to-field');const sync=()=>{const custom=period.value==='custom';monthField.hidden=custom;month.disabled=custom;fromField.hidden=!custom;toField.hidden=!custom;from.disabled=!custom;to.disabled=!custom;from.required=custom;to.required=custom;};period.addEventListener('change',sync);sync();document.querySelectorAll('[data-panel-toggle]').forEach(button=>button.addEventListener('click',()=>{const panel=document.getElementById(button.dataset.panelToggle),opening=panel.hidden;document.querySelectorAll('.invoice-toggle-panel').forEach(item=>item.hidden=true);document.querySelectorAll('[data-panel-toggle]').forEach(item=>item.setAttribute('aria-expanded','false'));panel.hidden=!opening;button.setAttribute('aria-expanded',opening?'true':'false');}));})();</script>
